module TopModule (
    input  logic        clk,
    input  logic        reset,
    input  logic [31:0] in,
    output logic [31:0] out
);

    logic [31:0] in_d;

    always_ff @(posedge clk) begin
        if (reset) begin
            out  <= 32'b0;
            in_d <= 32'b0;
        end else begin
            in_d <= in;
            for (int i = 0; i < 32; i++) begin
                if (in_d[i] && ~in[i]) begin
                    out[i] <= 1'b1;
                end
            end
        end
    end

endmodule

